 vocab=["η διάλεξη", "η ομιλία", "ο θαυμασμός", "γνήσιος", "η έκφραση", "η διασκευή", "η φήμη", "η ερμηνεύτρια", "το αγαλματίδιο", "η τελετή", "η απουσία", "συμπίπτω", "ηχογραφώ", "η ποίηση", "η παρέμβαση", "αιχμηρός", "προβάλλω", "η καρδιακή προσβολή"],
